import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the custom CUDA kernel for 4D tensor-matrix multiplication:
# C[b, i, j, k] = sum_l( A[b, i, j, l] * B[l, k] )
tensor_matmul_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cstdio>

__global__ void tensormatrixmul_kernel(const float* A, const float* B, float* C,
                                       int b, int i, int j, int l, int k) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = b * i * j * k;
    if (idx < total) {
        int k_idx = idx % k;
        int j_idx = (idx / k) % j;
        int i_idx = (idx / (j * k)) % i;
        int b_idx =  idx / (i * j * k);

        float val = 0.0f;
        for (int l_idx = 0; l_idx < l; ++l_idx) {
            int offsetA = (((b_idx * i + i_idx) * j + j_idx) * l) + l_idx;
            int offsetB = l_idx * k + k_idx;
            val += A[offsetA] * B[offsetB];
        }
        int offsetC = (((b_idx * i + i_idx) * j) + j_idx) * k + k_idx;
        C[offsetC] = val;
    }
}

torch::Tensor tensormatrixmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Ensure inputs are contiguous
    A = A.contiguous();
    B = B.contiguous();

    // Extract dimensions
    int b = A.size(0);
    int i = A.size(1);
    int j = A.size(2);
    int l = A.size(3);
    int k = B.size(1);

    auto options = A.options();
    auto C = torch::zeros({b, i, j, k}, options);

    int total = b * i * j * k;
    const int block_size = 256;
    const int grid_size = (total + block_size - 1) / block_size;

    tensormatrixmul_kernel<<<grid_size, block_size>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        b, i, j, l, k
    );

    return C;
}
"""

tensor_matmul_cpp_source = r"torch::Tensor tensormatrixmul_cuda(torch::Tensor A, torch::Tensor B);"

tensor_matmul = load_inline(
    name="tensormatrixmul",
    cpp_sources=tensor_matmul_cpp_source,
    cuda_sources=tensor_matmul_source,
    functions=["tensormatrixmul_cuda"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.tensor_matmul = tensor_matmul

    def forward(self, A, B):
        return self.tensor_matmul.tensormatrixmul_cuda(A, B)
